CREATE VIEW std_game_genre AS WITH genre_split AS (SELECT game_title, platform_name, main."trim"(genre_value) AS genre_value FROM std_inventory_game_ready , unnest(string_split(genre_raw, ',')) AS t(genre_value) WHERE (genre_raw IS NOT NULL)), genre_canonical AS (SELECT game_title, platform_name, CASE  WHEN ((genre_value ~~* 'Hack and slash/Beat ''em up')) THEN ('Hack and Slash/Beat ''em up') WHEN ((genre_value ~~* 'Turn-based strategy (TBS)')) THEN ('Turn-based Strategy (TBS)') ELSE genre_value END AS genre_name FROM genre_split)SELECT DISTINCT game_title, platform_name, genre_name FROM genre_canonical WHERE ((genre_name IS NOT NULL) AND (genre_name != ''));
